def add_months(start_date, months):
    if not start_date or not months:
        return False
    year = start_date.year + ((start_date.month - 1 + int(months)) // 12)
    month = ((start_date.month - 1 + int(months)) % 12) + 1
    month_days = [31, 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day = min(start_date.day, month_days[month - 1])
    return datetime.date(year, month, day)

for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    course = rec.x_training_course_id.sudo() if rec.x_training_course_id else False
    training_type = course.x_course_training_type_id.sudo() if course and course.x_course_training_type_id else False

    employee_name = employee.name or employee.display_name or 'Employee'
    course_name = course.x_course_name or course.display_name or 'Training Course'
    vals = {}

    if not rec.x_state:
        vals['x_state'] = 'draft'
    if not rec.x_commitment_state:
        vals['x_commitment_state'] = 'applied'
    if not rec.x_participation_state:
        vals['x_participation_state'] = 'allocated'
    if not rec.x_reference_code:
        vals['x_reference_code'] = 'HR-F-0008'
    if not rec.x_service_commitment_months:
        vals['x_service_commitment_months'] = 24
    if not rec.x_responsible_user_id:
        vals['x_responsible_user_id'] = env.user.id

    if training_type and rec.x_training_type_id != training_type:
        vals['x_training_type_id'] = training_type.id

    if course:
        vals['x_recovery_amount'] = course.x_seat_cost_amount or 0.0
        vals['x_recovery_amount_words'] = course.x_seat_cost_amount_words or ''
        vals['x_recovery_required_if_breached'] = bool(course.x_recovery_required_if_breached)
        if not rec.x_commitment_start_date and course.x_training_end_date:
            vals['x_commitment_start_date'] = course.x_training_end_date

    start_date = vals.get('x_commitment_start_date') or rec.x_commitment_start_date
    months = vals.get('x_service_commitment_months') or rec.x_service_commitment_months or 24
    end_date = add_months(start_date, months)
    if end_date:
        vals['x_commitment_end_date'] = end_date

    if not rec.x_document_reference or 'COURSE' in rec.x_document_reference:
        emp_part = employee.id if employee else 0
        course_part = course.id if course else 0
        vals['x_document_reference'] = 'HR-F-0008-EMP-%05d-%05d-%05d' % (emp_part, course_part, rec.id)

    normalized_name = '%s - %s - %s' % (employee_name, course_name, vals.get('x_state') or rec.x_state or 'draft')
    vals['x_name'] = normalized_name

    rec.write(vals)

    if employee:
        employee.message_post(
            body='تم إنشاء تعهد تدريب: %s' % normalized_name,
            subtype_xmlid='mail.mt_note',
        )

def add_months(start_date, months):
    if not start_date or not months:
        return False
    year = start_date.year + ((start_date.month - 1 + int(months)) // 12)
    month = ((start_date.month - 1 + int(months)) % 12) + 1
    month_days = [31, 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day = min(start_date.day, month_days[month - 1])
    return datetime.date(year, month, day)

for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    course = rec.x_training_course_id.sudo() if rec.x_training_course_id else False
    training_type = course.x_course_training_type_id.sudo() if course and course.x_course_training_type_id else False

    employee_name = employee.name or employee.display_name or 'Employee'
    course_name = course.x_course_name or course.display_name or 'Training Course'
    vals = {}

    if not rec.x_state:
        vals['x_state'] = 'draft'
    if not rec.x_commitment_state:
        vals['x_commitment_state'] = 'applied'
    if rec.x_state == 'signed' and rec.x_commitment_state == 'applied':
        vals['x_commitment_state'] = 'committed'
    if rec.x_is_breached and rec.x_commitment_state not in ('fulfilled', 'cancelled'):
        vals['x_commitment_state'] = 'breached'
    if not rec.x_participation_state:
        vals['x_participation_state'] = 'allocated'
    if not rec.x_reference_code:
        vals['x_reference_code'] = 'HR-F-0008'
    if not rec.x_service_commitment_months:
        vals['x_service_commitment_months'] = 24

    if training_type and rec.x_training_type_id != training_type:
        vals['x_training_type_id'] = training_type.id

    if course:
        if rec.x_recovery_amount != course.x_seat_cost_amount:
            vals['x_recovery_amount'] = course.x_seat_cost_amount or 0.0
        if rec.x_recovery_amount_words != course.x_seat_cost_amount_words:
            vals['x_recovery_amount_words'] = course.x_seat_cost_amount_words or ''
        if rec.x_recovery_required_if_breached != course.x_recovery_required_if_breached:
            vals['x_recovery_required_if_breached'] = bool(course.x_recovery_required_if_breached)
        if not rec.x_commitment_start_date and course.x_training_end_date:
            vals['x_commitment_start_date'] = course.x_training_end_date

    start_date = vals.get('x_commitment_start_date') or rec.x_commitment_start_date
    months = vals.get('x_service_commitment_months') or rec.x_service_commitment_months or 24
    end_date = add_months(start_date, months)
    if end_date and rec.x_commitment_end_date != end_date:
        vals['x_commitment_end_date'] = end_date

    if not rec.x_document_reference or 'COURSE' in rec.x_document_reference:
        emp_part = employee.id if employee else 0
        course_part = course.id if course else 0
        vals['x_document_reference'] = 'HR-F-0008-EMP-%05d-%05d-%05d' % (emp_part, course_part, rec.id)

    normalized_name = '%s - %s - %s' % (employee_name, course_name, vals.get('x_state') or rec.x_state or 'draft')
    if rec.x_name != normalized_name:
        vals['x_name'] = normalized_name

    if vals:
        rec.write(vals)

for rec in records.sudo():
    rec.write({'x_is_breached': True, 'x_commitment_state': 'breached'})
    if rec.x_employee_id:
        rec.x_employee_id.message_post(body='تم تسجيل تعهد التدريب كإخلال: %s' % (rec.x_name or rec.display_name), subtype_xmlid='mail.mt_note')

for rec in records.sudo():
    rec.write({'x_is_breached': False, 'x_commitment_state': 'fulfilled'})
    if rec.x_employee_id:
        rec.x_employee_id.message_post(body='تم تسجيل تعهد التدريب كمستوفى: %s' % (rec.x_name or rec.display_name), subtype_xmlid='mail.mt_note')

for rec in records.sudo():
    rec.write({'x_commitment_state': 'cancelled'})
    if rec.x_employee_id:
        rec.x_employee_id.message_post(body='تم إلغاء تعهد التدريب: %s' % (rec.x_name or rec.display_name), subtype_xmlid='mail.mt_note')
